return ['domain'=>'tassyir-for-woocommerce','plural-forms'=>'nplurals=6; plural=(n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 ? 4 : 5);','language'=>'ar','project-id-version'=>'Tassyir for WooCommerce 1.0.0','pot-creation-date'=>'2026-10-30T20:04:27+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['Send WooCommerce orders and products to Tassyir, with a cash-on-delivery order form. Every order is queued and retried until Tassyir confirms it.'=>'أرسل طلبات ومنتجات WooCommerce إلى Tassyir، مع نموذج طلب بالدفع عند الاستلام. كل طلب يُحفظ في قائمة انتظار ويُعاد إرساله حتى يؤكده Tassyir.','Sorry, you are not allowed to do this.'=>'عذرًا، لا تملك صلاحية القيام بذلك.','The cash-on-delivery form creates a normal WooCommerce order, which is then sent to Tassyir like any other. Delivery fees, wilayas, communes and desks come from your Tassyir store and carrier, so they are not set here.'=>'ينشئ نموذج الدفع عند الاستلام طلب WooCommerce عاديًا، يُرسَل بعدها إلى Tassyir مثل أي طلب آخر. أسعار التوصيل والولايات والبلديات والمكاتب تأتي من متجرك وشركة التوصيل في Tassyir، لذلك لا تُضبط هنا.','Place it anywhere with the shortcode %1$s (also in Elementor\'s shortcode widget) or the "%2$s" block.'=>'ضعه في أي مكان بالرمز المختصر %1$s (يعمل أيضًا في عنصر الرمز المختصر في Elementor) أو بمكوّن «%2$s».','Tassyir COD form'=>'نموذج الدفع عند الاستلام Tassyir','Placement'=>'مكان الظهور','Product pages'=>'صفحات المنتجات','Show on every product page'=>'إظهاره في كل صفحة منتج','Add to cart'=>'زر الإضافة إلى السلة','Replace Add to cart with the form'=>'استبدال زر الإضافة إلى السلة بالنموذج','Replace Add to cart, and hide the cart & checkout'=>'استبدال زر الإضافة إلى السلة، وإخفاء السلة وصفحة الدفع','Keep Add to cart under the form'=>'إبقاء زر الإضافة إلى السلة تحت النموذج','Fields'=>'الحقول','Quantity selector'=>'اختيار الكمية','Second phone (optional for the customer)'=>'هاتف ثانٍ (اختياري للزبون)','Address'=>'العنوان','Address is required'=>'العنوان إلزامي','Note'=>'ملاحظة','Icons in the fields'=>'أيقونات داخل الحقول','Desk delivery option (only where your carrier has a desk)'=>'خيار التوصيل للمكتب (فقط حيث يوجد مكتب لشركة التوصيل)','Quantity offers (from Tassyir)'=>'عروض الكمية (من Tassyir)','Show the saving on offers'=>'إظهار مقدار التوفير في العروض','Show'=>'إظهار','Language and texts'=>'اللغة والنصوص','Form language'=>'لغة النموذج','The site language (Arabic otherwise)'=>'لغة الموقع (وإلا العربية)','Text direction'=>'اتجاه النص','From the language'=>'حسب اللغة','Right to left'=>'من اليمين إلى اليسار','Left to right'=>'من اليسار إلى اليمين','Leave a text empty to keep the default shown in grey.'=>'اترك النص فارغًا للإبقاء على النص الافتراضي الظاهر بالرمادي.','Colours'=>'الألوان','Main colour (button, selection)'=>'اللون الرئيسي (الزر، الاختيار)','Button text'=>'نص الزر','Background'=>'الخلفية','Text'=>'النص','Borders'=>'الحدود','Corner radius'=>'استدارة الزوايا','After the order'=>'بعد الطلب','The customer sees'=>'يرى الزبون','WooCommerce\'s order received page'=>'صفحة «تم استلام الطلب» في WooCommerce','My own page (URL below)'=>'صفحتي الخاصة (الرابط أدناه)','A message on the form'=>'رسالة على النموذج','Thank-you page URL'=>'رابط صفحة الشكر','Order number and total are added as ?order=&total=. Orders Tassyir holds as possible spam get no WooCommerce order: with the order received page they see the message on the form instead.'=>'يُضاف رقم الطلب والمجموع بهذا الشكل ?order=&total=. الطلبات التي يحجزها Tassyir كاحتمال سبام لا يُنشأ لها طلب WooCommerce: مع صفحة «تم استلام الطلب» يرى أصحابها رسالة النموذج بدلًا منها.','Spam protection'=>'الحماية من الطلبات المزيفة','Tassyir checks every order before it exists (honeypot, phone and device limits, your spam rules). Behind Cloudflare, every visitor reaches your server from a Cloudflare address: tick this so Tassyir uses the visitor\'s real address instead (it checks that the request really came through Cloudflare).'=>'يفحص Tassyir كل طلب قبل إنشائه (فخ الروبوتات، حدود الهاتف والجهاز، قواعد السبام الخاصة بك). خلف Cloudflare يصل كل زائر إلى خادمك من عنوان Cloudflare: فعّل هذا الخيار ليستعمل Tassyir العنوان الحقيقي للزائر (ويتحقق من أن الطلب مرّ فعلًا عبر Cloudflare).','Cloudflare'=>'Cloudflare','My site is behind Cloudflare'=>'موقعي يعمل خلف Cloudflare','Pixels'=>'البكسلات','Sends Purchase with Tassyir\'s event id, so it deduplicates with Tassyir\'s server-side events. The pixel itself must already be on your site.'=>'يرسل حدث Purchase بمعرّف حدث Tassyir، فلا يتكرر مع أحداث Tassyir من جهة الخادم. يجب أن يكون البكسل نفسه مثبتًا مسبقًا في موقعك.','PixelYourSite is active and already sends Purchase from the order received page: keep these off to avoid counting each order twice.'=>'إضافة PixelYourSite مفعّلة وترسل Purchase من صفحة «تم استلام الطلب»: اترك هذه الخيارات معطّلة حتى لا يُحتسب كل طلب مرتين.','Meta Pixel'=>'بكسل Meta','Send Purchase'=>'إرسال Purchase','TikTok Pixel'=>'بكسل TikTok','Send CompletePayment'=>'إرسال CompletePayment','Save changes'=>'حفظ التغييرات','Heading'=>'العنوان الرئيسي','Button'=>'الزر','Success message'=>'رسالة النجاح','Name'=>'الاسم','Phone'=>'الهاتف','Second phone'=>'الهاتف الثاني','Wilaya'=>'الولاية','Commune'=>'البلدية','Home delivery'=>'التوصيل للمنزل','Desk delivery'=>'التوصيل للمكتب','Offers heading'=>'عنوان العروض','Under the total'=>'تحت المجموع','Order status is not imported (see your Tassyir settings)'=>'حالة الطلب غير مستوردة (راجع إعدادات Tassyir)','Order is older than the connection'=>'الطلب أقدم من تاريخ الربط','A product is not linked to a Tassyir product'=>'منتج غير مرتبط بمنتج في Tassyir','Order has no products'=>'الطلب لا يحتوي على منتجات','No active store in Tassyir'=>'لا يوجد متجر نشط في Tassyir','Tassyir order limit reached'=>'تم بلوغ حد الطلبات في Tassyir','Tassyir could not read this order'=>'تعذّر على Tassyir قراءة هذا الطلب','Tassyir is already processing this order'=>'Tassyir يعالج هذا الطلب حاليًا','Waiting: too many requests'=>'في الانتظار: طلبات كثيرة جدًا','Temporary error in Tassyir, will retry'=>'خطأ مؤقت في Tassyir، ستتم إعادة المحاولة','Tassyir could not import it'=>'تعذّر على Tassyir استيراده','The order could not be read in WooCommerce'=>'تعذّرت قراءة الطلب في WooCommerce','Could not reach Tassyir (network or host firewall)'=>'تعذّر الوصول إلى Tassyir (الشبكة أو جدار حماية الاستضافة)','Your server clock is wrong, so Tassyir refuses the requests'=>'ساعة الخادم لديك غير مضبوطة، لذا يرفض Tassyir الطلبات','Not connected to Tassyir'=>'غير مرتبط مع Tassyir','Tassyir refused the connection: please reconnect'=>'رفض Tassyir الاتصال: يرجى إعادة الربط','This site is connected to Tassyir another way: please reconnect'=>'هذا الموقع مرتبط مع Tassyir بطريقة أخرى: يرجى إعادة الربط','This plugin version is too old: please update it'=>'إصدار هذه الإضافة قديم جدًا: يرجى تحديثها','Tassyir is temporarily unavailable, will retry'=>'Tassyir غير متاح مؤقتًا، ستتم إعادة المحاولة','Tassyir could not read the data sent'=>'تعذّر على Tassyir قراءة البيانات المرسلة','Too large for Tassyir'=>'حجم كبير جدًا بالنسبة لـ Tassyir','This site is already linked to another Tassyir business. Disconnect it there first, or contact Tassyir support.'=>'هذا الموقع مرتبط بالفعل بنشاط تجاري آخر في Tassyir. افصله من هناك أولًا، أو تواصل مع دعم Tassyir.','The connection link is invalid or was already used. Please try again.'=>'رابط الربط غير صالح أو سبق استخدامه. يرجى المحاولة مجددًا.','The connection link expired. Please try again.'=>'انتهت صلاحية رابط الربط. يرجى المحاولة مجددًا.','The connection attempt could not be verified (it expired or was started by another user). Please try again.'=>'تعذّر التحقق من محاولة الربط (انتهت صلاحيتها أو بدأها مستخدم آخر). يرجى المحاولة مجددًا.','Connection cancelled.'=>'تم إلغاء الربط.','Your site address and your WordPress admin address differ (domain, http/https or port), so Tassyir cannot connect. Make them match (Settings → General) and try again.'=>'عنوان موقعك وعنوان لوحة تحكم ووردبريس مختلفان (النطاق أو http/https أو المنفذ)، لذا لا يستطيع Tassyir الاتصال. اجعلهما متطابقين (الإعدادات ← عام) ثم حاول مجددًا.','Tassyir sent an unexpected answer. Please try again.'=>'أرسل Tassyir ردًا غير متوقع. يرجى المحاولة مجددًا.','Tassyir refused the image (type or size)'=>'رفض Tassyir الصورة (النوع أو الحجم)','The product is not linked in Tassyir'=>'المنتج غير مرتبط في Tassyir','Image type not supported (JPEG, PNG, WebP or GIF only)'=>'نوع الصورة غير مدعوم (JPEG أو PNG أو WebP أو GIF فقط)','Image larger than 10 MB'=>'الصورة أكبر من 10 ميغابايت','Image file missing on the server'=>'ملف الصورة غير موجود على الخادم','Image file could not be read'=>'تعذّرت قراءة ملف الصورة','Tassyir error (HTTP %s)'=>'خطأ في Tassyir (HTTP %s)','Queued'=>'في الانتظار','Sent'=>'أُرسل','Skipped'=>'تم تخطيه','Failed'=>'فشل','Not sent'=>'لم يُرسل','Order'=>'طلب','Product'=>'منتج','Image'=>'صورة','Status check'=>'فحص الحالة','Connection'=>'الربط','Tassyir for WooCommerce needs WooCommerce 8.0 or newer. Please install and activate WooCommerce; until then the plugin does nothing.'=>'تحتاج إضافة Tassyir for WooCommerce إلى WooCommerce 8.0 أو أحدث. يرجى تثبيت WooCommerce وتفعيله؛ حتى ذلك الحين لا تقوم الإضافة بأي شيء.','Tassyir: this site must be reconnected. Orders are kept in the queue until then.'=>'Tassyir: يجب إعادة ربط هذا الموقع. تبقى الطلبات في قائمة الانتظار حتى ذلك الحين.','Tassyir: please update the Tassyir for WooCommerce plugin to version %s or newer. Orders are kept in the queue until then.'=>'Tassyir: يرجى تحديث إضافة Tassyir for WooCommerce إلى الإصدار %s أو أحدث. تبقى الطلبات في قائمة الانتظار حتى ذلك الحين.','Tassyir: your server clock is wrong (%s), so Tassyir refuses its requests. Ask your host to fix the server time.'=>'Tassyir: ساعة الخادم لديك غير مضبوطة (%s)، لذا يرفض Tassyir طلباته. اطلب من الاستضافة ضبط وقت الخادم.','Open Tassyir settings'=>'فتح إعدادات Tassyir','Tassyir: %d old manual WooCommerce webhook is no longer needed.'=>'Tassyir: لا توجد روابط Webhook يدوية قديمة.' . "\0" . 'Tassyir: رابط Webhook يدوي قديم واحد في WooCommerce لم يعد ضروريًا.' . "\0" . 'Tassyir: رابطا Webhook يدويان قديمان في WooCommerce لم يعودا ضروريين.' . "\0" . 'Tassyir: %d روابط Webhook يدوية قديمة في WooCommerce لم تعد ضرورية.' . "\0" . 'Tassyir: %d رابطًا يدويًا قديمًا في WooCommerce لم يعد ضروريًا.' . "\0" . 'Tassyir: %d رابط Webhook يدوي قديم في WooCommerce لم يعد ضروريًا.','Review and delete them'=>'مراجعتها وحذفها','Tassyir for WooCommerce is almost ready.'=>'إضافة Tassyir for WooCommerce جاهزة تقريبًا.','Connect this store to start sending your orders to Tassyir.'=>'اربط هذا المتجر لبدء إرسال طلباتك إلى Tassyir.','Connect to Tassyir'=>'الربط مع Tassyir','Don’t show again'=>'لا تُظهر هذا مجددًا','Sent on %s'=>'أُرسل في %s','%d attempt'=>'%d محاولة' . "\0" . 'محاولة واحدة' . "\0" . 'محاولتان' . "\0" . '%d محاولات' . "\0" . '%d محاولة' . "\0" . '%d محاولة','Send to Tassyir'=>'إرسال إلى Tassyir','%d order queued for Tassyir.'=>'لا طلبات في الانتظار لـ Tassyir.' . "\0" . 'أُضيف طلب واحد إلى قائمة انتظار Tassyir.' . "\0" . 'أُضيف طلبان إلى قائمة انتظار Tassyir.' . "\0" . 'أُضيفت %d طلبات إلى قائمة انتظار Tassyir.' . "\0" . 'أُضيف %d طلبًا إلى قائمة انتظار Tassyir.' . "\0" . 'أُضيف %d طلب إلى قائمة انتظار Tassyir.','Send to Tassyir again'=>'إعادة الإرسال إلى Tassyir','This store sends its orders and products to Tassyir (https://tassyir.io), the service the store uses to confirm and deliver orders. Nothing is sent before the store owner connects the store to Tassyir.'=>'يرسل هذا المتجر طلباته ومنتجاته إلى Tassyir (https://tassyir.io)، وهي الخدمة التي يستخدمها المتجر لتأكيد الطلبات وتوصيلها. لا يُرسَل أي شيء قبل أن يربط صاحب المتجر متجره بـ Tassyir.','When you place an order, these details are sent to Tassyir: your name, phone number, email address, billing and shipping addresses, the products ordered, the totals, the payment method and your order note. They are sent again when the order status changes.'=>'عند تقديم طلب، تُرسَل هذه البيانات إلى Tassyir: اسمك، رقم هاتفك، بريدك الإلكتروني، عنوانا الفوترة والشحن، المنتجات المطلوبة، المجاميع، طريقة الدفع وملاحظتك على الطلب. وتُرسَل مجددًا عند تغيّر حالة الطلب.','Tassyir also receives the store’s products and product photos, and technical information about the store (software versions and the size of the sending queue).'=>'يتلقى Tassyir أيضًا منتجات المتجر وصورها، ومعلومات تقنية عن المتجر (إصدارات البرامج وحجم قائمة الإرسال).','When you order with the store’s cash-on-delivery form, Tassyir also receives your IP address, your browser’s user agent and a random device identifier stored in your browser (local storage and a cookie named tsy_device_id), used to price the order and protect the store against fake orders.'=>'عند الطلب عبر نموذج الدفع عند الاستلام في المتجر، يتلقى Tassyir أيضًا عنوان IP الخاص بك، ومعرّف متصفحك (user agent)، ومعرّف جهاز عشوائيًا محفوظًا في متصفحك (التخزين المحلي وملف تعريف ارتباط باسم tsy_device_id)، لتسعير الطلب وحماية المتجر من الطلبات الوهمية.','Tassyir’s privacy policy: %s'=>'سياسة الخصوصية لـ Tassyir: %s','Settings'=>'الإعدادات','Checkout form'=>'نموذج الطلب','Connected to Tassyir. New orders are now sent automatically.'=>'تم الربط مع Tassyir. تُرسل الطلبات الجديدة الآن تلقائيًا.','Disconnected from Tassyir.'=>'تم فك الربط عن Tassyir.','Product sync started. It runs in the background, 20 products at a time.'=>'بدأت مزامنة المنتجات. تعمل في الخلفية، 20 منتجًا في كل مرة.','Orders are being queued in the background.'=>'تتم إضافة الطلبات إلى قائمة الانتظار في الخلفية.','The old manual webhooks were deleted.'=>'تم حذف روابط Webhook اليدوية القديمة.','The problems log was cleared.'=>'تم مسح سجل المشاكل.','Checkout form settings saved.'=>'تم حفظ إعدادات نموذج الطلب.','Please choose a valid date.'=>'يرجى اختيار تاريخ صحيح.','Connect your store to Tassyir'=>'اربط متجرك مع Tassyir','One last step: connect this store to start sending your orders to Tassyir.'=>'خطوة أخيرة: اربط هذا المتجر لبدء إرسال طلباتك إلى Tassyir.','You will choose your business and store on %s, then come back here.'=>'ستختار نشاطك التجاري ومتجرك على %s، ثم تعود إلى هنا.','Once connected, this plugin sends to your Tassyir store:'=>'بعد الربط، ترسل هذه الإضافة إلى متجرك في Tassyir:','Orders: every new order, kept in a queue and retried until Tassyir confirms it.'=>'الطلبات: كل طلب جديد، يُحفظ في قائمة انتظار ويُعاد إرساله إلى أن يؤكده Tassyir.','Products: names, prices, SKUs, variations and product photos, so Tassyir can create them.'=>'المنتجات: الأسماء والأسعار ورموز SKU والتنويعات وصور المنتجات، ليتمكن Tassyir من إنشائها.','Store health: plugin, WordPress and WooCommerce versions, and the queue size.'=>'حالة المتجر: إصدارات الإضافة وووردبريس وWooCommerce، وحجم قائمة الانتظار.','Business'=>'النشاط التجاري','Store'=>'المتجر','Status'=>'الحالة','Orders queue'=>'قائمة انتظار الطلبات','%1$d waiting, %2$d failed'=>'%1$d في الانتظار، %2$d فشلت','Last order sent'=>'آخر طلب أُرسل','None yet'=>'لا شيء بعد','Products'=>'المنتجات','Plugin version'=>'إصدار الإضافة','Sync all products'=>'مزامنة كل المنتجات','Reconnect'=>'إعادة الربط','Disconnect'=>'فك الربط','Disconnect this site from Tassyir? Orders will stop being sent.'=>'فك ربط هذا الموقع عن Tassyir؟ سيتوقف إرسال الطلبات.','See every Tassyir job in Scheduled Actions'=>'عرض كل مهام Tassyir في الإجراءات المجدولة','Checking…'=>'جارٍ التحقق…','Online'=>'متصل','Last seen %s ago'=>'آخر اتصال منذ %s','Never synced. New and edited products are sent automatically.'=>'لم تتم المزامنة بعد. تُرسل المنتجات الجديدة والمعدّلة تلقائيًا.','Sync running: %d product sent so far.'=>'المزامنة جارية: لم يُرسل أي منتج بعد.' . "\0" . 'المزامنة جارية: أُرسل منتج واحد حتى الآن.' . "\0" . 'المزامنة جارية: أُرسل منتجان حتى الآن.' . "\0" . 'المزامنة جارية: أُرسلت %d منتجات حتى الآن.' . "\0" . 'المزامنة جارية: أُرسل %d منتجًا حتى الآن.' . "\0" . 'المزامنة جارية: أُرسل %d منتج حتى الآن.','%1$d product synced on %2$s.'=>'لم تتم مزامنة أي منتج في %2$s.' . "\0" . 'تمت مزامنة منتج واحد في %2$s.' . "\0" . 'تمت مزامنة منتجين في %2$s.' . "\0" . 'تمت مزامنة %1$d منتجات في %2$s.' . "\0" . 'تمت مزامنة %1$d منتجًا في %2$s.' . "\0" . 'تمت مزامنة %1$d منتج في %2$s.','%1$s (version %2$s is available)'=>'%1$s (الإصدار %2$s متوفر)','Send orders since…'=>'إرسال الطلبات منذ…','Queues every order created since this date (90 days at most) that Tassyir has not received yet.'=>'يضيف إلى قائمة الانتظار كل طلب أُنشئ منذ هذا التاريخ (90 يومًا كحد أقصى) ولم يستلمه Tassyir بعد.','Date'=>'التاريخ','Send orders'=>'إرسال الطلبات','Old manual webhooks'=>'روابط Webhook اليدوية القديمة','Before this plugin, these WooCommerce webhooks sent your orders to Tassyir. The plugin now does it, so they are no longer needed (duplicates are ignored until you delete them).'=>'قبل هذه الإضافة، كانت روابط Webhook هذه في WooCommerce ترسل طلباتك إلى Tassyir. الإضافة تقوم بذلك الآن، لذا لم تعد ضرورية (يتم تجاهل الطلبات المكررة إلى أن تحذفها).','Delete them'=>'احذفها','Delete these webhooks permanently?'=>'حذف روابط Webhook هذه نهائيًا؟','Recent problems'=>'المشاكل الأخيرة','No problems.'=>'لا توجد مشاكل.','When'=>'الوقت','What'=>'العنصر','Problem'=>'المشكلة','Clear'=>'مسح','Cash on delivery'=>'الدفع عند الاستلام','Tassyir flagged this order as suspicious: check it before shipping.'=>'صنّف Tassyir هذا الطلب كمشبوه: تحقق منه قبل الشحن.','Second phone: %s'=>'الهاتف الثاني: %s','Order placed with the Tassyir COD form.'=>'طلب أُنشئ عبر نموذج الدفع عند الاستلام Tassyir.','Tassyir COD form: choose a product (or place the block on a product page). The site must be connected to Tassyir.'=>'نموذج Tassyir للدفع عند الاستلام: اختر منتجًا (أو ضع المكوّن في صفحة منتج). يجب أن يكون الموقع مربوطًا بـ Tassyir.','Tassyir for WooCommerce is incomplete (missing vendor files). Please reinstall it from the zip downloaded from your Tassyir dashboard.'=>'إضافة Tassyir for WooCommerce غير مكتملة (ملفات vendor مفقودة). يرجى إعادة تثبيتها من الملف المضغوط المحمّل من لوحة تحكم Tassyir.','Product ID'=>'معرّف المنتج','Leave empty on a product page: the form is for that product.'=>'اتركه فارغًا في صفحة منتج: يكون النموذج لذلك المنتج.','block titleTassyir COD form'=>'نموذج الدفع عند الاستلام Tassyir','block descriptionCash-on-delivery order form: wilaya, commune, home or desk delivery and Tassyir\'s live fees.'=>'نموذج طلب بالدفع عند الاستلام: الولاية، البلدية، التوصيل للمنزل أو للمكتب وأسعار Tassyir المباشرة.','block keywordcod'=>'الدفع عند الاستلام','block keywordorder'=>'طلب','block keywordtassyir'=>'tassyir','block keywordcheckout'=>'الدفع']];